INSERT INTO _seed_neuro_ap1_context (unit_id,actor_id) SELECT curricular_unit_id,updated_by FROM quiz_topics WHERE id='quiz-topic-neuro-ap1' AND status='published' AND deleted_at IS NULL LIMIT 1;
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-238',unit_id,'quiz-topic-neuro-ap1','Que tipo de ossificação predomina na base do crânio?',NULL,'Em termos gerais, os ossos da base do crânio formam-se a partir do condrocrânio por <strong>ossificação endocondral</strong>, enquanto os ossos da calota e grande parte do esqueleto facial se formam por ossificação intramembranosa. Alguns ossos, como esfenóide, temporal e occipital, têm constituição mista.<p><small>Gray’s Anatomy, 42.ª ed., cap. 17, pp. 288–290.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-238-answer','quiz-neuro-ap1-238','Ossificação endocondral',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-238-incorrect','quiz-neuro-ap1-238','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-239',unit_id,'quiz-topic-neuro-ap1','Que osso do neurocrânio é essencialmente endocondral e central nas fossas nasais?',NULL,'A cápsula nasal é inicialmente cartilagínea; a sua ossificação contribui para a lâmina orbitária e o labirinto do <strong>etmóide</strong>. Assim, este osso é um componente predominantemente endocondral do neurocrânio associado às fossas nasais.<p><small>Gray’s Anatomy, 42.ª ed., cap. 17, p. 289.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-239-answer','quiz-neuro-ap1-239','Etmóide',1,1);
