INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-253',unit_id,'quiz-topic-neuro-ap1','Quando se completa habitualmente a fusão esfeno-occipital?',NULL,'Desenvolvem-se predominantemente por ossificação endocondral e a maioria das suas articulações é formada inicialmente por cartilagem hialina, constituindo sincondroses. <strong>Uma das mais importantes é a sincondrose esfeno-occipital, entre o corpo do esfenóide anteriormente e a parte basilar do occipital posteriormente; a fusão completa-se geralmente entre os 13 e os 18 anos.</strong> Outras articulações cartilagíneas incluem as sincondroses occipitais e a placa de crescimento jugular ou articulação petro-exoccipital.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
