INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-254',unit_id,'quiz-topic-neuro-ap1','Que articulação sinovial une mandíbula e temporal?',NULL,'As principais articulações sinoviais associadas ao exterior do crânio são a <strong>articulação temporomandibular</strong>, entre a fossa mandibular do temporal e a apófise condilar da mandíbula, e a articulação atlanto-occipital, entre os côndilos occipitais e as facetas articulares superiores do atlas. Na articulação atlanto-occipital, os movimentos predominantes são flexão e extensão no plano anteroposterior e inclinação lateral bilateral no plano transversal; a rotação não é o movimento principal deste nível.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-254-answer','quiz-neuro-ap1-254','Articulação temporomandibular',1,1);
